    /**
     * Storybook story/docs id of THIS part's own component (e.g.
     * `"design-cards-continuecard-plain--progress"`). When set, the part's name
     * becomes a link that jumps straight to that story.
     */
    storyId?: string
    children?: Array<AnatomyNode>
}

/** Storybook manager route for a story id (breaks out of the preview iframe). */
const storyHref = (storyId: string) => `/?path=/story/${storyId}`

/**
 * ONE STATE of a leaf: what it renders, why that state exists, and how to call it.
 *
 * A leaf usually has several states that all come from DATA (a seat count, a null price, an
 * empty list). Before 2026-07-27 the panel had no idea they existed ΓÇö the author stacked them
 * by hand inside `children` with ad-hoc labels, so there was nowhere to explain a single state
 * and nowhere to put its own snippet. Worse, the deps tree was derived from the DOM of ALL the
 * stacked states at once, which made it correct for NONE of them: a state that renders nothing
 * still showed the nodes of its neighbours.
 *
 * Only the SELECTED state is mounted, so the tree the panel derives belongs to that state and
 * to nothing else.
 */
export interface AnatomyState {
    /** Tab label ΓÇö say what DATA produces the state (`"seats = 0"`, not `"empty"`). */
    name: string
    /** The component rendered in exactly that state. */
    render: ReactNode
    /** Why this state exists / what changes in it. Markdown allowed. */
    why?: ReactNode
    /** Snippet for THIS state ΓÇö the props that produce it. */
    code?: string
}

/** Props for the {@link BlockAnatomy} panel (ONE leaf). */
export interface BlockAnatomyProps {
    /** Block/design display name (header + tree root). */
    name: string
    tier: AnatomyTier
    /**
     * The leaf's states ΓÇö newest API (teacher picked layout C, 2026-07-27): a row of state tabs,
     * the selected state rendered large, and its OWN why/deps/code beside it.
     *
     * OPTIONAL on purpose. 663 leaves already pass `children` + one `note` + one `code`; they keep
     * working and are shown as a single implicit state, so both models live side by side while
     * stories migrate one at a time.
     */
    states?: Array<AnatomyState>
    /**
     * DEPS ΓÇö **story KH├üC** m├á leaf n├áy dß╗▒a v├áo (thß║ºy chß╗æt 2026-07-26).
     *
     * CHß╗ê khai component C├ô story ri├¬ng, V├Ç PHß║óI k├¿m `storyId` ΓÇö entry thiß║┐u
     * `storyId` kh├┤ng bß║Ñm nhß║úy ─æi ─æ├óu ─æ╞░ß╗úc n├¬n KH├öNG ─æ╞░ß╗úc t├¡nh l├á dep (thß║ºy chß╗æt
     * 2026-07-26 lß║ºn 2: "deps kh├┤ng c├│ th├¼ th├┤i"). Span nß╗Öi bß╗Ö cß╗ºa atom (`Label`,
     * `Icon`, `Spinner`, `SuffixIcon`) c┼⌐ng KH├öNG phß║úi deps c├╣ng l├╜ do.
     *
     * OPTIONAL: atom l├í bß╗ìc thß║│ng HeroUI th├¼ KH├öNG c├│ deps ΓÇö bß╗Å hß║│n prop n├áy
     * (neo: `Button.Base` rß╗ùng ┬╖ `Button.Group` khai ─æ├║ng c├íi n├│ dß╗▒ng lß║íi).
     *
     * @deprecated ─É╞░ß╗¥ng C┼¿ khai Lß║áI cß║Ñu tr├║c bß║▒ng tay n├¬n tr├┤i khß╗Åi h├¼nh (neo:
     * `TruthList` khai `Skeleton.Indicator` m├á block thß║¡t ─æ├ú bß╗Å). Story mß╗¢i d├╣ng
     * {@link BlockAnatomyProps.annotate}: c├óy dß╗▒ng tß╗½ DOM, tay chß╗ë ghi WHY.
     */
    parts?: Array<AnatomyNode>
    /**
     * ─É╞»ß╗£NG Mß╗ÜI ΓÇö ch├║ giß║úi cho c├óy DOM (thß║ºy chß╗æt 2026-07-26).
     *
     * Cß║Ñu tr├║c c├óy LU├öN ─æß║┐n tß╗½ DOM; bß║úng n├áy chß╗ë th├¬m `role`/`tier`/`storyId` cho
     * part n├áo cß║ºn, v├á ─æß╗ông thß╗¥i l├á **DANH S├üCH TRß║«NG**: part kh├┤ng khai th├¼ kh├┤ng
     * v├áo c├óy. Entry KH├öNG c├│ `storyId` c┼⌐ng kh├┤ng v├áo c├óy (─æß╗ìc kß╗╣ ß╗ƒ
     * {@link BlockAnatomyProps.parts}). Bß╗Å trß╗æng hoß║╖c rß╗ùng sau lß╗ìc ΓåÆ tab Deps
     * KH├öNG hiß╗çn ra (thay v├¼ b├ío "no deps" nh╞░ tr╞░ß╗¢c 2026-07-26).
     */
    annotate?: Record<string, AnatomyAnnotation>
    /**
     * THIS leaf's live render. Legacy path ΓÇö a leaf that declares {@link BlockAnatomyProps.states}
     * passes each render inside its state instead, and leaves this out.
     */
    children?: ReactNode
    /** Leaf label shown in the header (e.g. `"Prop variant"`). */
    leaf?: string
    /** Short one-liner: what makes THIS leaf's composition/shape what it is. */
    note?: ReactNode
    /** Optional fuller rationale for the whole composite (usually only on the main leaf). */
    reason?: ReactNode
    /** Usage snippet for THIS leaf ΓÇö shown in the Code tab with a Copy button. */
    code?: string
    /**
     * Class cho RI├èNG khung render (th╞░ß╗¥ng l├á `mx-auto max-w-xl`) ΓÇö bß╗ü ngang cß╗ºa CHß╗ª THß╗é.
     *
     * Tr╞░ß╗¢c 2026-07-27 story tß╗▒ bß╗ìc cß║ú `BlockAnatomy` trong mß╗Öt `div.max-w-xl`, n├¬n panel thß╗½a
     * h╞░ß╗ƒng lu├┤n 576px: ba cß╗Öt chß╗» nhß╗ôi v├áo ─æ├│ th├ánh `Copy` bß╗ï cß║»t, `why` g├úy s├íu d├▓ng, c├óy deps
     * g├úy n─âm d├▓ng (thß║ºy bß║»t qua ß║únh). Bß╗ü ngang l├á thuß╗Öc t├¡nh cß╗ºa thß╗⌐ ─ÉANG ─É╞»ß╗óC Vß║╝, kh├┤ng phß║úi
     * cß╗ºa c├íi panel n├│i vß╗ü n├│, n├¬n n├│ v├áo ─æ├óy v├á panel giß╗» nguy├¬n bß╗ü ngang v├╣ng chß╗⌐a.
     */
    renderClassName?: string
}

/**
 * M├ÇU Tß║ªNG cho c├óy DOM (thß║ºy duyß╗çt 2026-07-26) ΓÇö bß║úng PH├éN LOß║áI, cß╗æ ├╜ KH├öNG d├╣ng
 * token ngß╗» ngh─⌐a (`warning`/`success`/`danger`): tß║ºng l├á loß║íi, kh├┤ng phß║úi trß║íng
 * th├íi. C├╣ng l├╜ lß║╜ ─æ├ú ├íp cho ramp ─æß╗Ö kh├│ cß╗ºa `VariantChip`.
 *
 * ΓÜá∩╕Å Ng╞░ß╗úc lß║íi, bß║úng phß╗º ß╗ƒ tab States th├¼ ─É├ÜNG l├á ngß╗» ngh─⌐a (─æß╗º / thiß║┐u) n├¬n ß╗ƒ ─æ├│
 * d├╣ng thß║│ng token `success`/`danger`.
 */
const TIER_PILL: Record<AnatomyTier, string> = {
    heroui: "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-100",
    frame: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-100",
    composite: "bg-sky-100 text-sky-800 dark:bg-sky-900 dark:text-sky-100",
