    block: "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-100",
    atom: "bg-default text-muted",
}

/** Thanh dß║½n dß╗ìc ΓÇö c├╣ng hß╗ç m├áu vß╗¢i pill, nhß║ít h╞ín mß╗Öt nß║Ñc. */
const TIER_RAIL: Record<AnatomyTier, string> = {
    heroui: "border-amber-400",
    frame: "border-blue-400",
    composite: "border-sky-400",
    screen: "border-rose-400",
    block: "border-purple-400",
    atom: "border-default",
}

/**
 * Nh├ún tß║ºng hiß╗çn ra. `frame` v├á `composite` thay cho `primitive` (2026-07-27): tß║ºng c┼⌐ ─æo ra
 * hai bß║ún chß║Ñt ΓÇö 7 khung slot-tr╞í v├á 37 component sß╗ƒ hß╗»u vai nß╗Öi dung.
 */
const TIER_NAME: Record<AnatomyTier, string> = {
    heroui: "heroui",
    frame: "frame",
    composite: "composite",
    screen: "screen",
    block: "block",
    atom: "atom",
}

/** Props for {@link SideHeading}. */
interface SideHeadingProps {
    /** Section label ΓÇö one or two words, lower case. */
    children: ReactNode
}

/**
 * Nh├ún nhß╗Å cß╗ºa mß╗Öt mß╗Ñc trong panel b├¬n (`why this state` ┬╖ `deps` ┬╖ `code`).
 *
 * T├ích ra v├¼ ba chß╗ù d├╣ng c├╣ng mß╗Öt h├¼nh: viß║┐t tay ba lß║ºn th├¼ lß║ºn thß╗⌐ t╞░ sß║╜ lß╗çch.
 */
const SideHeading = ({ children }: SideHeadingProps) => (
    <h4 className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-muted">{children}</h4>
)

/** Pill nhß╗Å d├╣ng chung cho tier/state ΓÇö gom lß║íi ─æß╗â ba chß╗ù kh├┤ng lß╗çch nhau. */
const PILL = "rounded-full px-2 text-[11px] font-medium leading-5"

/**
 * Bß║ún ─æß╗ô thß║╗ cho {@link Prose} ΓÇö dß╗▒ng Sß║┤N ß╗ƒ module scope, kh├┤ng tß║ío lß║íi mß╗ùi render
 * (react-markdown so s├ính tham chiß║┐u; object mß╗¢i mß╗ùi l╞░ß╗út sß║╜ ├⌐p parse lß║íi).
 *
 * `p` ΓåÆ `<span className="block">` chß╗⌐ KH├öNG phß║úi `<p>`: mß║Ñy chß╗ù gß╗ìi ─æang nß║▒m sß║╡n
 * trong `<p>`/`<span>` (d├▓ng `role` trong c├óy), m├á `<p>` lß╗ông `<p>` th├¼ tr├¼nh duyß╗çt
 * tß╗▒ cß║»t thß║╗ v├á c├óy DOM vß╗í ngay.
 */
/**
 * What every markdown override receives. ONE named shape for all of them: eight slots with the
 * identical body would otherwise carry eight copies of the same inline type, and eight copies
 * are eight chances to drift.
 */
interface ProseSlotProps {
    /** Rendered children of the markdown node. */
    children?: ReactNode
}

/** The `a` slot additionally receives the href. */
interface ProseLinkProps extends ProseSlotProps {
    /** Link target as written in the markdown source. */
    href?: string
}

const PROSE_MARKS = {
    code: ({ children }: ProseSlotProps) => (
        <code className="rounded bg-default px-1 font-mono text-[0.9em] text-foreground">{children}</code>
    ),
    strong: ({ children }: ProseSlotProps) => (
        <strong className="font-semibold text-foreground">{children}</strong>
    ),
    em: ({ children }: ProseSlotProps) => <em className="italic">{children}</em>,
    a: ({ href, children }: ProseLinkProps) => (
        <a href={href} target="_top" className="text-accent underline-offset-2 hover:underline">
            {children}
        </a>
    ),
    ul: ({ children }: ProseSlotProps) => <ul className="list-disc pl-4">{children}</ul>,
    ol: ({ children }: ProseSlotProps) => <ol className="list-decimal pl-4">{children}</ol>,
}

/**
 * BLOCK ΓÇö ─æoß║ín v─ân ─æß╗⌐ng ri├¬ng (`reason`/`note` d╞░ß╗¢i panel). `p` ΓåÆ `<span
 * className="block">` chß╗⌐ KH├öNG phß║úi `<p>`: chß╗ù gß╗ìi c├│ khi ─æ├ú nß║▒m trong `<p>`/`<span>`,
 * m├á `<p>` lß╗ông `<p>` th├¼ tr├¼nh duyß╗çt tß╗▒ cß║»t thß║╗ v├á c├óy DOM vß╗í.
 */
const PROSE_COMPONENTS = {
    ...PROSE_MARKS,
    p: ({ children }: ProseSlotProps) => <span className="block">{children}</span>,
}

/**
 * INLINE ΓÇö chß╗» nß║▒m C├ÖNG D├ÆNG vß╗¢i thß╗⌐ kh├íc (`┬╖ {leaf}` tr├¬n header, `┬╖ {role}` trong
 * c├óy). ─Éß╗â `block` ß╗ƒ ─æ├│ th├¼ dß║Ñu `┬╖` bß╗ï ─æß║⌐y l├¬n mß╗Öt d├▓ng ri├¬ng.
 */
const PROSE_COMPONENTS_INLINE = {
    ...PROSE_MARKS,
    p: ({ children }: ProseSlotProps) => <>{children}</>,
}

/**
 * Chß╗» giß║úi th├¡ch cß╗ºa panel, render MARKDOWN (thß║ºy chß╗æt 2026-07-26).
 *
 * Chß╗ë string mß╗¢i ─æi qua markdown; `reason`/`note` khai kiß╗âu `ReactNode` n├¬n story
 * n├áo ─æ╞░a JSX vß║½n render y nguy├¬n ΓÇö kh├┤ng ├⌐p chuß╗ùi ho├í thß╗⌐ vß╗æn ─æ├ú l├á node.
 */
/** Props for {@link Prose}. */
interface ProseProps {
    /** Only a `string` goes through markdown; a node is rendered as-is. */
    children?: ReactNode
    /** Placement class only. */
    className?: string
    /** `true` ΓåÆ `p` renders as a fragment so the text stays on the caller's line. */
    inline?: boolean
}

const Prose = ({ children, className, inline = false }: ProseProps) => {
    if (typeof children !== "string") {
        return <span className={className}>{children}</span>
    }
    return (
        <span className={className}>
            <ReactMarkdown remarkPlugins={[remarkGfm]} components={inline ? PROSE_COMPONENTS_INLINE : PROSE_COMPONENTS}>
                {children}
            </ReactMarkdown>
        </span>
    )
}

/**
 * R├║t mß║úng `parts` VIß║╛T TAY (─æ╞░ß╗¥ng c┼⌐) th├ánh bß║úng ch├║ giß║úi phß║│ng.
 *
 * Chß╗ë giß╗» phß║ºn WHY (`role`/`tier`/`state`/`storyId`) ΓÇö phß║ºn **cß║Ñu tr├║c** trong ─æ├│ bß╗ï
 * Bß╗Ä, v├¼ cß║Ñu tr├║c nay lu├┤n suy tß╗½ DOM. Nhß╗¥ vß║¡y story c┼⌐ giß╗» nguy├¬n chß╗» giß║úi th├¡ch
 * m├á KH├öNG phß║úi sß╗¡a file n├áo.
 */
const flattenParts = (nodes: Array<AnatomyNode>, into: Record<string, AnatomyAnnotation> = {}) => {
    nodes.forEach((node) => {
        if (!(node.name in into)) {
            into[node.name] = { role: node.role, tier: node.tier, state: node.state, storyId: node.storyId }
        }
        if (node.children) {
            flattenParts(node.children, into)
        }
    })
    return into
}

export const BlockAnatomy = ({
    name,
    tier,
    parts,
    states,
    children,
    leaf,
    note,
    reason,
    code,
    annotate,
    renderClassName,
}: BlockAnatomyProps) => {
    // Mß╗ÿT ─É╞»ß╗£NG DUY NHß║ñT (thß║ºy chß╗æt 2026-07-26): cß║Ñu tr├║c lu├┤n suy tß╗½ DOM. Kh├┤ng c├│
    // bß║ún panel n├áo chß║íy song song ΓÇö hai bß║ún cho c├╣ng mß╗Öt viß╗çc th├¼ bß║ún c┼⌐ sß╗æng m├úi.
    //
