/**
 * Ruß╗Öt cß╗ºa panel: qu├⌐t DOM ra c├óy, rß╗ôi b├áy ba tab quanh n├│.
 *
 * Hai l╞░ß╗út render l├á b├¼nh th╞░ß╗¥ng: l╞░ß╗út 1 ch╞░a c├│ c├óy (ch╞░a c├│ DOM), l╞░ß╗út 2 render lß║íi
 * vß╗¢i c├óy ─æ├ú suy. So chuß╗ùi JSON tr╞░ß╗¢c khi `setState` ─æß╗â kh├┤ng lß║╖p v├┤ hß║ín.
 */
const BlockAnatomyDerived = ({
    name,
    tier,
    states,
    children,
    leaf,
    note,
    reason,
    code,
    annotate,
    renderClassName,
}: Omit<BlockAnatomyProps, "parts"> & { annotate: Record<string, AnatomyAnnotation> }) => {
    const hostRef = useRef<HTMLDivElement>(null)

    /**
     * Bß╗Ö state cß╗ºa leaf. Story c┼⌐ (`children` + mß╗Öt `note` + mß╗Öt `code`) ─æ╞░ß╗úc coi l├á Mß╗ÿT state
     * ß║⌐n danh, n├¬n 663 leaf hiß╗çn c├│ kh├┤ng phß║úi sß╗¡a g├¼ m├á vß║½n l├¬n ─æ├║ng bß╗æ cß╗Ñc mß╗¢i.
