    /**
     * Leaf CH╞»A di tr├║ sang `states[]`. Nh├ún cß╗ºa panel phß║úi n├│i kh├íc ─æi, v├¼ t├íc giß║ú c├│ thß╗â ─æ├ú
     * xß║┐p NHIß╗ÇU state bß║▒ng tay trong `children`: d├ín "why this state" l├¬n ─æ├│ l├á n├│i dß╗æi, mß╗Öt
     * c├óu ch├║ th├¡ch cho hai ba state. Neo: `TrialConversionStrip.Default` xß║┐p 2 h├áng dß╗» liß╗çu
     * trong `children` v├á panel d├ín ngay "WHY THIS STATE" l├¬n cß║ú hai (thß║ºy bß║»t 2026-07-27).
     */
    const isLegacyLeaf = !states || states.length === 0

    const [pickedState, setPickedState] = useState(0)
    // Kß║╣p chß╗ë sß╗æ tß║íi chß╗ù thay v├¼ d├╣ng effect: story ─æß╗òi leaf l├ám mß║úng ngß║»n lß║íi th├¼ r╞íi vß╗ü 0,
    // kh├┤ng cß║ºn mß╗Öt l╞░ß╗út render d╞░ ─æß╗â sß╗¡a state.
    const activeIndex = pickedState < stateList.length ? pickedState : 0
    const active = stateList[activeIndex]

    const [derived, setDerived] = useState<Array<AnatomyNode>>([])
    // Shiki cß║ºn biß║┐t nß╗ün s├íng hay tß╗æi; ─æß╗ìc tß╗½ ch├¡nh DOM ─æang bß╗ìc panel.
    const [isDark, setIsDark] = useState(false)
    useEffect(() => {
        const host = hostRef.current
