            // PHA A (re-point): c├óy leo `data-component` ΓÇö danh t├¡nh LU├öN-Bß║¼T do frame tß╗▒
            // ph├ít, thay `data-anat-part` (nh├⌐t tay + gated `showAnatomy`). `annotate` giß╗¥
            // key theo t├¬n component. Scaffold c┼⌐ c├▓n nguy├¬n tß╗¢i khi Pha B bulk-xo├í.
            const els = Array.from(host.querySelectorAll<HTMLElement>("[data-component]"))
            const order: Array<string> = []
            els.forEach((el) => {
                const nm = el.getAttribute("data-component") ?? ""
                // Γ¡É `annotate` l├á DANH S├üCH TRß║«NG (┬º11a, thß║ºy chß╗æt 2026-07-26) ΓÇö V├Ç tß╗½
                // 2026-07-26 (lß║ºn 2) c├▓n lß╗ìc th├¬m: chß╗ë nhß║¡n part c├│ `storyId` THß║¼T.
                //
                // DOM ph├ít ra cß║ú RUß╗ÿT cß╗ºa component con (`Callout` ph├ít
                // `Icon`/`Content`/`Title`/`Description`/`Action`). Vß║╜ ch├║ng ß╗ƒ ─æ├óy l├á
                // ─É├ÇO V├ÇO c├íi ─æ├ú c├│ story ri├¬ng ΓÇö kß╗â hai lß║ºn, v├á ─æß║╗ ra node kh├┤ng bß║Ñm
                // ─æ╞░ß╗úc v├¼ ch├║ng l├á KHE chß╗⌐ kh├┤ng phß║úi component.
                //
                // Tr╞░ß╗¢c ─æ├óy chß╗ë cß║ºn C├ô Mß║╢T trong `annotate` l├á v├áo c├óy, kß╗â cß║ú khi
                // `storyId` bß╗Å trß╗æng ΓÇö ra mß╗Öt "dep" kh├┤ng bß║Ñm ─æi ─æ├óu ─æ╞░ß╗úc (neo:
                // `Spinner.Base` tß╗▒ khai part "Spinner" trß╗Å v├áo ch├¡nh n├│). "Deps" giß╗¥
                // ─æ├║ng ngh─⌐a: c├│ `storyId` mß╗¢i t├¡nh, kh├┤ng th├¼ TH├öI ΓÇö kh├┤ng v├áo c├óy,
                // kh├┤ng chiß║┐m chß╗ù trong tab.
                if (nm && annotate[nm]?.storyId && !order.includes(nm)) {
                    order.push(nm)
                }
            })
            // Γ¡É Gom node theo PHß║ªN Tß╗¼, kh├┤ng theo T├èN (thß║ºy chß╗æt 2026-07-27).
            //
            // Bß║ún c┼⌐ kho├í theo chuß╗ùi t├¬n: `firstEl` chß╗ë giß╗» phß║ºn tß╗¡ ─Éß║ªU TI├èN cß╗ºa mß╗ùi t├¬n, n├¬n hai
            // `Stack.H` trong c├╣ng mß╗Öt c├óy NHß║¼P l├ám mß╗Öt v├á c├óy ─æß╗ìc sai. C├ích n├⌐ ─æang d├╣ng l├á bß╗ïa
            // t├¬n ri├¬ng (`Stack.H.PriceRow`, `Stack.V.Price`) ΓÇö nh╞░ng ─æ├│ kh├┤ng phß║úi t├¬n component,
            // v├á ng╞░ß╗¥i ─æß╗ìc bß║Ñm v├áo sß║╜ tra mß╗Öt c├íi t├¬n kh├┤ng tß╗ôn tß║íi.
            //
            // Kho├í theo phß║ºn tß╗¡ th├¼ c├╣ng mß╗Öt component xuß║Ñt hiß╗çn bao nhi├¬u lß║ºn c┼⌐ng ─æ╞░ß╗úc, mß╗ùi lß║ºn
            // l├á mß╗Öt node ri├¬ng, v├á T├èN quay vß╗ü ─æ├║ng vai cß╗ºa n├│: nh├ún ─æß╗â tra ch├║ giß║úi, kh├┤ng phß║úi
            // ─æß╗ïnh danh.
            const nodeEls = els.filter((el) => {
                const nm = el.getAttribute("data-component") ?? ""
                // `heroui` v├áo c├óy m├á KH├öNG cß║ºn `storyId`: n├│ l├á component cß╗ºa th╞░ viß╗çn, kh├┤ng c├│
                // story cß╗ºa ta ─æß╗â bß║Ñm sang. Giß║Ñu n├│ ─æi l├á ─æß╗â c├óy n├│i dß╗æi bß║▒ng c├ích bß╗Å s├│t.
                const meta = annotate[nm]
                return Boolean(nm && (meta?.storyId || meta?.tier === "heroui"))
            })
            const parentElOf = new Map<HTMLElement, HTMLElement | null>()
            nodeEls.forEach((el) => {
                let node = el.parentElement
                let parent: HTMLElement | null = null
                while (node && node !== host) {
                    if (nodeEls.includes(node)) {
                        parent = node
                        break
                    }
                    node = node.parentElement
                }
                parentElOf.set(el, parent)
            })
            const toNode = (el: HTMLElement): AnatomyNode => {
                const nm = el.getAttribute("data-component") ?? ""
                const meta = annotate[nm]
                const kids = nodeEls.filter((child) => parentElOf.get(child) === el)
                return {
                    name: nm,
                    tier: meta?.tier ?? "composite",
                    role: meta?.role,
                    state: meta?.state,
                    storyId: meta?.storyId,
                    ...(kids.length > 0 ? { children: kids.map(toNode) } : {}),
