            }
            const next = nodeEls.filter((el) => parentElOf.get(el) === null).map(toNode)
            // So chuß╗ùi TR╞»ß╗ÜC khi set ΓÇö nß║┐u kh├┤ng sß║╜ setState mß╗ùi l╞░ß╗út render ΓåÆ lß║╖p.
