        //
        // ΓÜá∩╕Å 2026-07-26: tr╞░ß╗¢c ─æ├óy qu├⌐t CHß╗ê nß║▒m trong `requestAnimationFrame`. Iframe
        // preview bß╗ï tr├¼nh duyß╗çt throttle (tab nß╗ün, cß╗¡a sß╗ò kh├┤ng vß║╜) th├¼ rAF KH├öNG BAO
        // GIß╗£ fire ΓåÆ `derived` rß╗ùng v─⌐nh viß╗àn ΓåÆ tab Deps biß║┐n mß║Ñt d├╣ story khai ─æ├║ng.
        // Nh├¼n ra ─æ├║ng nh╞░ mß╗Öt lß╗ùi cß║Ñu h├¼nh story, m├á thß║¡t ra l├á panel kh├┤ng chß║íy.
        scan()
        raf = requestAnimationFrame(scan)
        const ro = new ResizeObserver(() => {
            cancelAnimationFrame(raf)
            raf = requestAnimationFrame(scan)
        })
        ro.observe(host)
