            cancelAnimationFrame(raf)
            ro.disconnect()
        }
    // `activeIndex` PHß║óI nß║▒m trong deps: vß╗¢i API `states`, `children` kh├┤ng ─æß╗òi khi bß║Ñm sang
    // state kh├íc, n├¬n nß║┐u chß╗ë khai `[children, annotate]` th├¼ effect kh├┤ng chß║íy lß║íi v├á c├óy deps
    // ─æß╗⌐ng nguy├¬n cß╗ºa state tr╞░ß╗¢c. ─Éo ─æ╞░ß╗úc: state `seatsRemaining = null` render 0 node m├á panel
    // vß║½n hiß╗çn 4 link cß╗ºa state ─æß║ºu.
    }, [children, annotate, activeIndex])

    /**
     * Mß╗Öt nh├ính ΓÇö T├èN + pill tier + vai tr├▓. Kh├┤ng sß╗æ, kh├┤ng badge chß╗ông l├¬n h├¼nh.
     * Thanh dß║½n dß╗ìc mang M├ÇU Cß╗ªA CHA: liß║┐c m├áu l├á biß║┐t nh├ính n├áy ─æß║╗ tß╗½ tß║ºng n├áo,
     * khß╗Åi phß║úi d├▓ ng╞░ß╗úc l├¬n.
     */
    /** Props for one {@link Branch} of the derived tree. */
    interface BranchProps {
        /** The node being drawn. */
        node: AnatomyNode
        /** Nesting depth ΓÇö drives the rail colour and indent. */
        depth: number
    }

    const Branch = ({ node, depth }: BranchProps) => (
        <div
            className={cn(
                depth > 0 && "border-l-2 pl-3",
                depth > 0 && TIER_RAIL[node.tier],
            )}
        >
            <div className="flex flex-wrap items-baseline gap-2 py-1">
                {/* C├│ `storyId` ΓåÆ t├¬n part th├ánh LINK mß╗ƒ ─æ├║ng story cß╗ºa ch├¡nh n├│
                (target `_top` ─æß╗â tho├ít iframe preview). Kh├┤ng c├│ ΓåÆ chß╗» th╞░ß╗¥ng. */}
                {node.storyId ? (
                    <a
                        href={storyHref(node.storyId)}
                        target="_top"
                        className="font-mono text-xs text-accent underline-offset-2 hover:underline"
                    >
                        {node.name}
                    </a>
                ) : (
                    <span className="font-mono text-xs text-foreground">{node.name}</span>
                )}
                <span className={cn(PILL, TIER_PILL[node.tier])}>{TIER_NAME[node.tier]}</span>
                {node.state ? (
                    <span className="rounded-full border border-default px-2 text-[11px] leading-5 text-muted">
                        {node.state}
                    </span>
                ) : null}
                {node.role ? (
                    <span className="text-xs text-muted">
