        return () => {
            if (copyTimer.current) {
                clearTimeout(copyTimer.current)
            }
        }
    }, [])
    const handleCopy = () => {
        void navigator.clipboard?.writeText(active.code ?? "")
        setIsCopied(true)
        if (copyTimer.current) {
            clearTimeout(copyTimer.current)
        }
        copyTimer.current = setTimeout(() => setIsCopied(false), 1200)
    }

    return (
        <div ref={hostRef} data-tier="fixture" className="flex flex-col gap-6">
            {/* H├îNH cß╗ºa state ─æang chß╗ìn ΓÇö CHß╗ê state n├áy ─æ╞░ß╗úc mount, n├¬n c├óy deps panel suy ra
                thuß╗Öc ─æ├║ng n├│. Tr╞░ß╗¢c 2026-07-27 mß╗ìi state xß║┐p chung trong `children` n├¬n c├óy
                trß╗Ön lß║½n v├á kh├┤ng ─æ├║ng vß╗¢i state n├áo cß║ú. */}
            <div className={renderClassName}>{active.render}</div>

            {/* `@container` NGAY TR├èN panel (thß║ºy chß╗æt A, 2026-07-27): biß║┐n `@app-md:` b├¬n d╞░ß╗¢i
                ─æo Bß╗Ç NGANG Cß╗ªA PANEL. Thiß║┐u d├▓ng n├áy th├¼ n├│ ─æo `@container` gß║ºn nhß║Ñt l├á CANVAS,
                n├¬n luß║¡t hai cß╗Öt bung ra ngay cß║ú khi panel chß╗ë rß╗Öng 576px ΓÇö ─æ├║ng c├íi ─æ├ú l├ám `Copy`
                bß╗ï cß║»t v├á `why` g├úy s├íu d├▓ng. */}
            <div
