                    <span className={cn(PILL, TIER_PILL[tier])}>{TIER_NAME[tier]}</span>
                    {/* `leaf` c┼⌐ng ─æß║ºy `` `t├¬n prop` `` n├¬n ─æi qua markdown nh╞░ reason/note. */}
                    {leaf ? (
                        <span className="text-[11px] text-muted">
                            ┬╖ <Prose inline>{leaf}</Prose>
                        </span>
                    ) : null}
                    {stateList.length > 1 ? (
                        <span className="ml-auto text-[11px] text-muted">
                            {stateList.length} states
                        </span>
                    ) : null}
                </div>

                {/* H├áng tab STATE. Mß╗Öt state th├¼ khß╗Åi b├áy ΓÇö leaf c┼⌐ tr├┤ng y nh╞░ tr╞░ß╗¢c. */}
                {stateList.length > 1 ? (
