import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Community membership feature container.
 *
 * A single-product purchase surface ($5/month equivalent): premium tech blog,
 * private community, course discount, recruitment exposure. Opening the shared
 * payment overlay with {@link PaymentFlow.Membership} lets the user pick a
 * gateway, which then runs `purchaseMembership` + redirects to checkout.
 * Mounted by the `/profile/membership` route. `"use client"` because it reads
 * the payment overlay singleton and routes.
 */
export const MembershipPage = () => {
    const t = useTranslations()
    // shared payment modal ΓÇö opening it with the membership flow runs the purchase
    const { open: openPaymentModal } = usePaymentOverlayState()


    /** Perk rows shown under the price ΓÇö each is a translated benefit line. */
    const perks = useMemo(
        () => [
            t("membership.perks.blog"),
            t("membership.perks.community"),
            t("membership.perks.discount"),
            t("membership.perks.recruitment"),
        ],
        [
            t,
        ],
    )

    /** Open the shared payment modal for the membership flow. */
    const onSubscribe = useCallback(
        () => {
            // hand the membership flow to the modal ΓÇö it creates the checkout
            // with whichever payment method the user picks, then redirects
            openPaymentModal({
                flow: PaymentFlow.Membership,
            })
        },
        [
            openPaymentModal,
        ],
    )

    const cardItems = [
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <Typography type="h5" weight="semibold">
                            {t("membership.card.title")}
                        </Typography>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("membership.card.desc")}
                        </Typography>
                    ),
                ]}
            />
        ),
        () => (
            <div className="flex flex-col gap-0">
                <StackH
                    gap={3}
                    align="end"
                    principle="value-row"
                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                    items={[
                        () => (
                            <Typography type="h3" weight="bold">
                                {t("membership.price")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" className="pb-1">
                                {t("membership.priceHint")}
                            </Typography>
                        ),
                    ]}
                />
                <Typography type="body-xs" color="muted">
                    {t("membership.priceApprox")}
                </Typography>
            </div>
        ),
        () => (
            <CheckListCard>
                {perks.map((perk) => (
                    <CheckListItem key={perk}>
                        <Typography type="body-sm">{perk}</Typography>
                    </CheckListItem>
                ))}
            </CheckListCard>
        ),
        () => (
            <Button
                variant="primary"
                fullWidth
                onPress={onSubscribe}
            >
                {t("membership.cta")}
            </Button>
        ),
    ]

    return (
        <Box identity={{ tier: "page", component: "MembershipPage" }} principle="center-measure" className="mx-auto max-w-2xl"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <div className="flex flex-col gap-10">
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("membership.title")} />}
                        title={t("membership.title")}
                        description={t("membership.subtitle")}
                    />
                    <Card className="flex flex-col">
                        <Card.Content>
                            <StackV gap={6} items={cardItems} />
                        </Card.Content>
                    </Card>
                </div>
            </Box>
        </Box>
    )
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"

import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { ListRow } from "@/components/composites/lists/List"
import { PageHeader } from "@/components/composites/layout/Page"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@/components/blocks/learn/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@/components/blocks/learn/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` ΓÇö the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet ΓåÆ
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built ΓÇö `onOpenSettings` is a chrome trigger only.
 *
 * PRESENTATIONAL ΓÇö every input arrives as a prop; this twin owns no data of
 * its own, so `index.tsx` IS the presentational file (no separate connected
 * wrapper, no `component.tsx` split) ΓÇö mirrors `MindMapPage`'s convention.
 *
 * Emits its own identity (`data-tier="page"` / `data-component="PersonalProjectTaskPage"`)
 * unconditionally, handed down to the root `Container` via its `identity` prop
 * (see `frames/_identity.ts`) rather than drawn on a wrapper `div` of its own
 * (`tiers/block.md` BLOCK-2: a page never draws a shape of its own) ΓÇö same as
 * `split.md`'s "Identity is data-tier + data-component" section. The
 * breadcrumb sits in a `StackH inline` (shrink-to-content sizing) rather
 * than a raw `div`.
 */

/** One personal-project schema-v1 evaluation criterion ΓÇö the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit ΓåÆ the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission ΓÇö see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs ΓÇö the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set ΓåÆ the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed ΓÇö chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` ΓåÆ the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` ΓåÆ the evaluate CTA is disabled (the caller's own combined business rule ΓÇö locked, syncing, ΓÇª). */
    isEvaluateDisabled?: boolean
    /** `true` ΓåÆ at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present ΓåÆ the score card renders; omit ΓåÆ nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA ΓÇö `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` ΓåÆ this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric ΓÇö only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides ΓÇö only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` ΓåÆ every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (┬º12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row ΓÇö a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row ΓÇö the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => {
    const guideSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Guide" />
            {legacyMarkdown(item.guide)}
        </>
    )
    const exampleSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Example" />
            {legacyMarkdown(item.example)}
        </>
    )
    return (
        <StackV
            gap={4}

            items={[
                () => <StackV gap={2} items={[() => guideSection]} />,
                () => <StackV gap={2} items={[() => exampleSection]} />,
            ]}
        />
    )
}

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
const readingColumn = (props: {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const legacyAccordions = (
        <>
            {hasLegacyCriteria || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={criteriaItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
            {hasLegacyCode || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={codeItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    const readingSections = (
        <>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <StackH
                            inline
                            gap={1}
                            body={() => (
                                <Breadcrumbs collapseOnMobile collapseFrom={4} items={breadcrumbItems ?? []} isSkeleton={isSkeleton} />
                            )}
                        />
                    ) : undefined
                }
                title={task.title}
                description={task.description}
            />

            {!isSkeleton && isLocked ? (
                <Callout
                    status="warning"
                    title="Preview of a task not yet unlocked"
                    description="You need to finish the current task before you can work on this one."

                />
            ) : null}

            {showBrief ? (
                <SurfaceCard
                    label="Guide"
                    isSkeleton={isSkeleton}

                    body={() => <MarkdownContent source={brief.body} />}
                />
            ) : null}

            {showLegacy ? (
                <SurfaceCard
                    label="Evaluation criteria (legacy)"
                    isSkeleton={isSkeleton}

                    body={() => <StackV gap={6} items={[() => legacyAccordions]} />}
                />
            ) : null}

            <ContentRelatedList
                label={relatedLabel}
                items={relatedItems}
                isSkeleton={isSkeleton}

            />
        </>
    )

    return <StackV gap={7} isSkeleton={isSkeleton} items={[() => readingSections]} />
}

/**
 * The persistent, sticky act column: repo URL + settings summary trigger +
 * evaluate/secondary actions + the latest graded result. A private render
 * helper (see file header), not an anatomy node of its own.
 */
const submissionPanel = (props: {
    panel: PersonalProjectTaskSubmissionPanelProps
    isSkeleton: boolean
}) => {
    const { panel, isSkeleton } = props
    const hasAttempts = panel.hasAttempts ?? false

    const evaluateActions = (
        <>
            <Button
                label={hasAttempts ? "Re-evaluate" : "Evaluate"}
                prefixIcon={SparkleIcon}
                onPress={panel.onEvaluate}
                isPending={panel.isEvaluatePending}
                isDisabled={panel.isEvaluateDisabled}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View feedback"
                variant="tertiary"
                onPress={panel.onOpenFeedbackDetails}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
            <Button
                label="View submission history"
                variant="tertiary"
                onPress={panel.onOpenAttempts}
                isDisabled={!hasAttempts}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const githubFields = (
        <>
            <InputText
                label="GitHub repo URL"
                value={panel.repoUrl}
                onValueChange={panel.onRepoUrlChange}
                errorMessage={panel.repoUrlError}
                placeholder="https://github.com/ΓÇª"
                ariaLabel="GitHub repo URL"
                isSkeleton={isSkeleton}

            />
            <div>
                <ListRow
                    leading={SettingsLeading}
                    title="Grading settings"
                    meta={() => <Typography size="sm" color="muted" text={`${panel.settingsLangLabel} ┬╖ ${panel.settingsBranch}`} />}
                    trailing={SettingsChevron}
                    onPress={panel.onOpenSettings}
                    isSkeleton={isSkeleton}

                />
            </div>
            <StackH gap={3} at="sm" principle="flex-action" isSkeleton={isSkeleton} items={[() => evaluateActions]}
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            />
        </>
    )

    const panelSections = (
        <>
            <SurfaceCard
                label="Project GitHub"
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => githubFields]} />}
            />

            {isSkeleton || panel.result != null ? (
                <SubmissionScoreCard
                    label="Latest grading result"
                    score={panel.result?.score ?? 0}
                    maxScore={panel.result?.maxScore}
                    isPassing={panel.result?.isPassing ?? true}
                    passScore={panel.result?.passScore}
                    shortFeedback={panel.result?.shortFeedback}
                    gradedByModel={panel.result?.gradedByModel}
                    modelCategory={panel.result?.modelCategory}
                    timeAgo={panel.result?.timeAgo}
                    isSkeleton={isSkeleton}


                />
            ) : null}
        </>
    )

    return <StackV gap={6} isSkeleton={isSkeleton} items={[() => panelSections]} />
}

/**
 * The personal-project task solve screen. See the file header for the function
 * list, the reuse map, and the two-column layout's known limits.
 *
 * @param props - {@link PersonalProjectTaskPageProps}
 */
const PersonalProjectTaskPage = ({
    breadcrumbItems,
    task,
    isLocked = false,
    brief,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    submissionPanelProps,
    isSkeleton = false,
}: PersonalProjectTaskPageProps) => (
    <Container
        identity={{ tier: "page", component: "PersonalProjectTaskPage" }}
        size="xl"
        padding={6}
        body={() => (
            <SplitWorkspace

                main={() => readingColumn({
                    breadcrumbItems,
                    task,
                    isLocked,
                    brief,
                    legacyCriteria,
                    legacyCodeImplementations,
                    relatedItems,
                    relatedLabel,
                    isSkeleton,
                })}
                aside={() => submissionPanel({ panel: submissionPanelProps, isSkeleton })}
            />
        )}
    />
)

export { PersonalProjectTaskPage }

"use client"

import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    PuzzlePieceIcon,
} from "@phosphor-icons/react"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import { pathConfig } from "@/resources/path"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { QueryUserSolvedChallengeItemData } from "@/modules/api/graphql/queries/types/user-solved-challenges"

/** Props for {@link ChallengeCourseRow}. */
export interface ChallengeCourseRowProps {
    /** Profile owner's username ΓÇö routes the row to `.challenges().course(courseSlug)`. */
    username: string | null
    /** Course title for this group, or null for ungrouped (V1-legacy) rows. */
    courseTitle: string | null
    /** SEO-friendly slug of the course, or null when unresolved (V1-legacy) ΓÇö the row is non-interactive without it. */
    courseSlug: string | null
    /** Solved-challenge rows under this course, in source order (list-item data). */
    items: Array<QueryUserSolvedChallengeItemData>
    /**
     * Total challenges in the course ΓÇö makes the bar a PROGRESS bar (done coloured
     * by difficulty, the rest the empty track). Omit/0 ΓåÆ pure passed-mix (100% fill).
     */
    totalChallenges?: number
}

/**
 * One course group on the Challenges tab: a framed puzzle {@link IconTile}, the
 * course title, a 4-tone difficulty {@link SegmentBar} and a passed-count summary.
 * The WHOLE glance row is a nav link (row-as-link, hover underlines the title) to
 * the per-course MANAGE page (`.challenges().course(courseSlug)`) ΓÇö search /
 * filter / sort of that course's submissions lives there, not inline here.
 *
 * @param props - {@link ChallengeCourseRowProps}
 */
export const ChallengeCourseRow = ({
    username,
    courseTitle,
    courseSlug,
    items,
    totalChallenges}: ChallengeCourseRowProps) => {
    const t = useTranslations()
    const locale = useLocale()

    const segments = buildDifficultySegments(items)
    const href = username && courseSlug
        ? pathConfig().locale(locale).profile(username).challenges().course(courseSlug).build()
        : undefined

    return (
        <SurfaceListCardItem
            href={href}
            hover="underline"
        >
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="start" items={[
                    () => (
                        <IconTile
                            size="sm"
                            icon={<PuzzlePieceIcon aria-hidden focusable="false" />}
                        />
                    ),
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            classNames={["min-w-0", "flex-1"]} items={[
                                () => (
                                    <Typography
                                        type="body-sm"
                                        weight="medium"
                                        truncate
                                        className={href ? "underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline" : undefined}
                                    >
                                        {courseTitle ?? t("publicProfile.challengesTab.ungrouped")}
                                    </Typography>
                                ),
                                () => (
                                    <SegmentBar
                                        hideLegend
                                        max={totalChallenges && totalChallenges > 0 ? totalChallenges : undefined}
                                        ariaLabel={t("publicProfile.challengesTab.submissionCount", { count: items.length })}
                                        segments={segments}
                                    />
                                ),
                                () => (
                                    <Typography type="body-xs" color="muted">
                                        {totalChallenges && totalChallenges > 0
                                            ? t("publicProfile.challengesTab.submissionProgress", { passed: items.length, total: totalChallenges })
                                            : t("publicProfile.challengesTab.submissionCount", { count: items.length })}
                                    </Typography>
                                ),
                            ]} />
                    ),
                ]} />
        </SurfaceListCardItem>
    )
}

"use client"

import React from "react"
import {
    Label,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    buildDifficultySegments,
} from "@/modules/utils/challenge-difficulty"
import {
    groupByCourse,
} from "@/modules/utils/group-challenges-by-course"
import {
    ChallengeCourseRow,
} from "./ChallengeCourseRow"
import { useQueryUserChallengeStrengthSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserChallengeStrengthSwr"
import { useQueryUserCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCoursesSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserSolvedChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSolvedChallengesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Props for {@link ProfileChallenges}. */
export type ProfileChallengesProps = Record<string, never>
/**
 * Challenges tab ΓÇö the profile owner's graded-challenge proof of work. Leads with
 * a passed count + a 4-tone difficulty {@link SegmentBar} (easyΓåÆgreen /
 * mediumΓåÆyellow / hardΓåÆred / insaneΓåÆpurple), then the submission list rendered as
 * Projects-tab-style rows: one collapsible {@link ChallengeCourseRow} per course
 * (its own difficulty bar + count), expanded on demand to reveal the repo links.
 * Self-contained: reads the username from the route, resolves it to the entity id,
 * and drives its own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileChallenges = () => {
    const t = useTranslations()
    // route carries the username; resolve to the entity id the query keys off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserSolvedChallengesSwr(userId)
    // difficulty-weighted challenge strength: global percentile + rank (null until passed)
    const { data: strength } = useQueryUserChallengeStrengthSwr(userId)
    // joined courses ΓåÆ total challenges per course (for the per-course progress bar)
    const { data: coursesData } = useQueryUserCoursesSwr(userId)
    const totalChallengesByCourse = new Map(
        (coursesData ?? []).map((course) => [course.label, course.challengeTotal]),
    )

    const challenges = data ?? []
    // difficulty distribution across all passed challenges (the headline bar)
    const difficultySegments = buildDifficultySegments(challenges)
    // language breadth: count per language, skipping rows with no language
    const langCounts = challenges.reduce<Record<string, number>>((acc, challenge) => {
        if (!challenge.selectedLang) {
            return acc
        }
        acc[challenge.selectedLang] = (acc[challenge.selectedLang] ?? 0) + 1
        return acc
    }, {})
    const langs = Object.entries(langCounts).sort((a, b) => b[1] - a[1])
    // submission list grouped by course (when the backend resolves titles)
    const groups = groupByCourse(challenges)

    // headline metric row (Coding-tab style): passed + XP + percentile + rank.
    // XP is the REAL ledger sum from the backend (NOT a FE sum of scores).
    const metricStats: Array<{ key: string; value: string }> = [
        { key: "passed", value: String(challenges.length) },
    ]
    if (strength?.xp != null) {
        metricStats.push({ key: "xp", value: String(strength.xp) })
    }
    if (strength?.percentile != null) {
        metricStats.push({ key: "percentile", value: `${strength.percentile}%` })
    }
    if (strength?.rank != null) {
        metricStats.push({ key: "rank", value: `#${strength.rank}` })
    }

    const rootClassNames: Array<AllowedClassName> = []


    return (
        <AsyncContent
            isLoading={(isLoading || !userId) && challenges.length === 0}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <SurfaceCardList
                                label={t("publicProfile.challengesTab.statsHeading")}
                                isSkeleton
                                items={[
                                    {
                                        key: "difficulty",
                                        content: () => <Skeleton.SegmentBar legendItems={4} />,
                                    },
                                    {
                                        key: "language",
                                        content: () => <Skeleton.SegmentBar legendItems={4} />,
                                    },
                                ]}
                            />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <SurfaceCardList
                                        isSkeleton
                                        items={[0, 1, 2].map((row) => ({
                                            key: `repo-skel-${row}`,
                                            content: () => (
                                                <StackH gap={4} principle="content-row" align="start"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.ProgressBar />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                    ]} />
                                            ),
                                        }))}
                                    />
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={challenges.length === 0}
            emptyContent={{
                title: t("publicProfile.challengesTab.empty"),
                description: t("publicProfile.challengesTab.emptyHint"),
            }}
            error={challenges.length === 0 ? error : undefined}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.challengesTab.metricsHeading")} frameless>
                            <StatRibbon
                                items={metricStats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.challengesTab.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    () => {
                        const statsItems: Array<SurfaceCardListItem> = [
                            ...(difficultySegments.length > 0
                                ? [{
                                    key: "difficulty",
                                    content: () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.difficultyHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.difficultyHeading")}
                                                        segments={difficultySegments}
                                                    />
                                                ),
                                            ]} />
                                    ),
                                } satisfies SurfaceCardListItem]
                                : []),
                            ...(langs.length > 0
                                ? [{
                                    key: "language",
                                    content: () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Label>{t("publicProfile.challengesTab.languageHeading")}</Label>,
                                                () => (
                                                    <SegmentBar
                                                        ariaLabel={t("publicProfile.challengesTab.languageHeading")}
                                                        segments={langs.map(([lang, count]) => ({
                                                            key: lang,
                                                            label: getLanguageLabel(lang),
                                                            value: count,
                                                            color: getLanguageColor(lang),
                                                        }))}
                                                    />
                                                ),
                                            ]} />
                                    ),
                                } satisfies SurfaceCardListItem]
                                : []),
                        ]
                        return (
                            <SurfaceCardList
                                label={t("publicProfile.challengesTab.statsHeading")}
                                items={statsItems}
                            />
                        )
                    },
                    () => (
                        <LabeledCard
                            label={t("publicProfile.challengesTab.repoHeading")}
                            frameless
                        >
                            <SurfaceListCard>
                                {groups.map((group, groupIndex) => (
                                    <ChallengeCourseRow
                                        key={group.courseTitle ?? `__ungrouped-${groupIndex}`}
                                        username={username}
                                        courseTitle={group.courseTitle}
                                        courseSlug={group.courseSlug}
                                        items={group.items}
                                        totalChallenges={group.courseTitle
                                            ? totalChallengesByCourse.get(group.courseTitle)
                                            : undefined}
                                    />
                                ))}
                            </SurfaceListCard>
                        </LabeledCard>
                    ),
                ]} />
        </AsyncContent>
    )
}

