"use client"

import React from "react"
import {
    cn,
    Chip,
    Typography,
} from "@heroui/react"
import {
    ArrowSquareOutIcon,
    SealCheckIcon,
    GraduationCapIcon,
    CodeIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import type { QueryUserPinnedProjectItem } from "@/modules/api/graphql/queries/types/user-pinned-projects"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Tech-stack chips shown inline before collapsing the rest into a "+N" chip. */
const MAX_TECH_CHIPS = 3

/** Props for {@link PinnedProjectCard}. */
export interface PinnedProjectCardProps {
    /** The pinned project to render (list-item data prop ΓÇö store can't index it). */
    pin: QueryUserPinnedProjectItem
}

/**
 * Display-only card for one pinned project (public-profile showcase, GitHub-pinned
 * style).
 *
 * @param props - {@link PinnedProjectCardProps}
 */
export const PinnedProjectCard = ({ pin}: PinnedProjectCardProps) => {
    const t = useTranslations()

    const isCourse = pin.type === "course"
    const TypeIcon = isCourse ? GraduationCapIcon : CodeIcon
    const title = pin.title ?? t("pinnedProjects.untitled")

    const tech = pin.techStack ?? []
    const visibleTech = tech.slice(0, MAX_TECH_CHIPS)
    const overflow = tech.length - visibleTech.length

    const chipItems = [
        ...visibleTech.map((techName) => (
            () => (
                <Chip key={techName} variant="soft" size="sm">
                    <Chip.Label>{techName}</Chip.Label>
                </Chip>
            )
        )),
        ...(overflow > 0
            ? [() => (
                <Chip variant="soft" size="sm">
                    <Chip.Label>{`+${overflow}`}</Chip.Label>
                </Chip>
            )]
            : []),
    ]

    const body = (
        <>
            <Box principle="card-padding" className="p-4"
                explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                <StackV gap={3} principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <StackH gap={3} principle="flex-action" justify="between"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            className={cn("inline-flex items-center rounded-full px-2 py-0 text-xs",
                                                isCourse
                                                    ? "bg-success-soft text-success-soft-foreground"
                                                    : "border border-default text-muted",
                                            )}
                                        >
                                            <StackH gap={2} principle="icon-text" inline
                                                explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                items={[
                                                    () => <TypeIcon className="size-4" aria-hidden="true" focusable="false" />,
                                                    () => <span>{isCourse ? t("pinnedProjects.typeCapstone") : t("pinnedProjects.typeExternal")}</span>,
                                                ]} />
                                        </span>
                                    ),
                                    () => (
                                        <ArrowSquareOutIcon
                                            className="size-4 shrink-0 text-muted"
                                            aria-hidden="true"
                                            focusable="false"
                                        />
                                    ),
                                ]} />
                        ),
                        () => (
                            <Typography
                                type="body-sm"
                                weight="medium"
                                className="line-clamp-2 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
                            >
                                {title}
                            </Typography>
                        ),
                        ...(pin.description
                            ? [() => (
                                <Typography type="body-xs" color="muted" className="line-clamp-1">
                                    {pin.description}
                                </Typography>
                            )]
                            : []),
                        ...(visibleTech.length > 0
                            ? [() => <Cluster gap={3} principle="chip-row" explain="Lets chips share one wrapping row so related tags stay together without stacking as a column." items={chipItems} />]
                            : []),
                    ]} />
            </Box>
            {pin.isVerified ? (
                <Box principle="pill-pad" className="border-t border-success/30 bg-success-soft px-4 py-2"
                    explain="Pill/chip inset ΓÇö not control-pad, because this pads a compact badge shape rather than a form control.">
                    <StackH gap={3} items={[
                        () => (
                            <SealCheckIcon
                                className="size-4 shrink-0 text-success-soft-foreground"
                                aria-hidden="true"
                                focusable="false"
                            />
                        ),
                        () => (
                            <Typography type="body-xs" weight="medium" className="text-success-soft-foreground">
                                {t("pinnedProjects.verifiedByStarci")}
                            </Typography>
                        ),
                    ]} />
                </Box>
            ) : null}
        </>
    )

    const cardClassName = cn(
        "group flex flex-col overflow-hidden rounded-2xl border bg-surface",
        pin.isVerified ? "border-success/40" : "border-default")

    if (pin.url) {
        return (
            <a
                href={pin.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={t("pinnedProjects.openAria", { title })}
                className={cn(cardClassName, "cursor-pointer")}
            >
                {body}
            </a>
        )
    }

    return <div className={cardClassName}>{body}</div>
}

"use client"

import React from "react"
import { Link } from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    PencilIcon,
} from "@phosphor-icons/react"
import { useProfileUsername } from "@/hooks/profile/useProfileUsername"
import { PinnedProjectCard } from "./PinnedProjectCard"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { usePinnedProjectsOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryUserPinnedProjectsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserPinnedProjectsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useAppSelector } from "@/redux/hooks"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

type ProfilePinnedActionProps = { label: string; onPress: () => void }

const ProfilePinnedAction = ({ label, onPress }: ProfilePinnedActionProps) => (
    <Link
        onPress={onPress}
        className="inline-flex shrink-0 cursor-pointer items-center text-sm text-accent-soft-foreground no-underline transition-opacity hover:opacity-60"
    >
        <StackH gap={2} principle="icon-text"
            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            inline items={[
                () => <PencilIcon className="size-4" aria-hidden="true" focusable="false" />,
                () => <span>{label}</span>,
            ]} />
    </Link>
)

/** Props for {@link ProfilePinned}. */
export type ProfilePinnedProps = WithClassNames<undefined>

/**
 * Pinned projects card on the public profile ΓÇö the user's hand-picked showcase
 * (verified course capstones + free-form external projects), GitHub-pinned-repos
 * style. Self-contained container: resolves the viewed user from the route, fetches
 * their pins via SWR, and renders one {@link PinnedProjectCard} per pin (verified
 * course pins get a "Verified by StarCi" chip; external pins link out).
 *
 * Owner-only: when the signed-in viewer owns this profile an "Add / manage"
 * action opens the manage modal (zustand overlay). Renders the empty state for
 * the owner (with an add CTA) but nothing at all for visitors with no pins, so a
 * stranger's profile stays clean.
 *
 * @param props - {@link ProfilePinnedProps}
 */
export const ProfilePinned = () => {
    const t = useTranslations()
    const username = useProfileUsername()
    const viewer = useAppSelector((state) => state.user.user)
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserPinnedProjectsSwr(userId)
    // manage modal (owner only) ΓÇö open-state lives in the shared zustand overlay
    const { open: openManage } = usePinnedProjectsOverlayState()

    // viewing your own profile ΓåÆ show the add/manage affordance + owner empty state
    const isSelf = !!viewer && !!userId && viewer.id === userId
    const pins = data ?? []

    // visitor viewing a profile with no pins and nothing loading/erroring ΓåÆ hide the
    // whole section (clean profile). Owners always keep the card (header + add CTA).
    if (!isSelf && !isLoading && !error && pins.length === 0) {
        return null
    }

    // frameless ONLY once real pins render (each PinnedProjectCard self-frames);
    // while loading/empty(owner CTA)/erroring there is no bounded surface, so
    // LabeledCard's own Card must frame it ΓÇö otherwise it renders bare on the page.
    const hasPins = !error && pins.length > 0

    return (
        <LabeledCard
            frameless={hasPins}
            label={t("pinnedProjects.heading")}
            action={isSelf && pins.length > 0
                ? () => <ProfilePinnedAction label={t("pinnedProjects.manage")} onPress={openManage} />
                : undefined}

        >
            <AsyncContent
                isLoading={isLoading && !data}
                skeleton={(
                    <Grid
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        columns={{ base: 1, sm: 2 }}
                        items={[0, 1, 2, 3].map((index) => ({
                            key: `pin-skel-${index}`,
                            content: () => (
                                <Box principle="card-padding" className="rounded-2xl border border-default bg-surface p-4"
                                    explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                    <StackV gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <StackH gap={3} principle="flex-action"
                                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                    justify="between" items={[
                                                        () => <Skeleton.Chip />,
                                                        () => <Skeleton className="size-4 shrink-0 rounded" />,
                                                    ]} />
                                            ),
                                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                            () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                            () => (
                                                <Cluster gap={3} principle="chip-row"
                                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                    items={
                                                        [0, 1, 2].map((chip) => (
                                                            () => <Skeleton.Chip key={chip} />
                                                        ))
                                                    } />
                                            ),
                                        ]} />
                                </Box>
                            ),
                        }))}
                    />
                )}
                isEmpty={pins.length === 0}
                // owner sees an add CTA; a visitor sees nothing (clean profile)
                emptyContent={isSelf ? {
                    title: t("pinnedProjects.emptyOwnerTitle"),
                    description: t("pinnedProjects.emptyOwnerDescription"),
                    onRetry: openManage,
                    retryLabel: t("pinnedProjects.add"),
                } : undefined}
                error={error}
                errorContent={{
                    title: t("pinnedProjects.errorTitle"),
                    description: t("pinnedProjects.errorDescription"),
                    onRetry: () => mutate(),
                    retryLabel: t("pinnedProjects.retry"),
                }}
            >
                <Grid
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    columns={{ base: 1, sm: 2 }}
                    items={pins.map((pin) => ({
                        key: pin.id,
                        content: () => <PinnedProjectCard pin={pin} />,
                    }))}
                />
            </AsyncContent>
        </LabeledCard>
    )
}

