/** One of the current user's installment ("trß║ú g├│p") plans (mirrors backend `InstallmentPlanItem`). */
export interface InstallmentPlanItem {
    /** Plan id ΓÇö pass to `payNextInstallment`. */
    id: string
    /** `"Fixed"` (new-buyer, N-month schedule) or `"FlexiblePool"` (legacy arrears pool). */
    planType: string
    /** Lifecycle status, e.g. `"Active"` | `"Overdue"` | `"Defaulted"` | `"Completed"`. */
    status: string
